-- Tenant-scoped server pagination for every Catalog directory.
CREATE OR REPLACE FUNCTION catalogo.productos_pagina(p_estado text,p_busqueda text,p_limit integer,p_offset integer)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,catalogo,plataforma,pg_temp AS $$
DECLARE tenant uuid:=plataforma.current_app_tenant_id();items jsonb;total bigint;
BEGIN
 IF p_limit NOT BETWEEN 1 AND 100 OR p_offset<0 THEN RAISE EXCEPTION 'Invalid pagination' USING ERRCODE='22023';END IF;
 IF plataforma.has_current_tenant_capability('erp.catalog','catalog.products.read') IS NOT TRUE THEN RAISE EXCEPTION 'Product access denied' USING ERRCODE='42501';END IF;
 SELECT count(*) INTO total FROM catalogo.productos p WHERE p.tenant_id=tenant AND(p_estado IS NULL OR p.estado=p_estado)AND(NULLIF(btrim(p_busqueda),'')IS NULL OR p.nombre ILIKE '%'||btrim(p_busqueda)||'%' OR p.codigo ILIKE '%'||btrim(p_busqueda)||'%');
 SELECT COALESCE(jsonb_agg(item ORDER BY name,id),'[]') INTO items FROM(SELECT p.nombre name,p.id,jsonb_build_object('id',p.id,'code',p.codigo,'name',p.nombre,'description',p.descripcion,'price',p.precio,'status',p.estado,'category_ref',p.categoria_ref,'image_url',p.imagen_url,'attributes',p.atributos,'external_reference',p.referencia_externa,'created_at',p.creado_en,'updated_at',p.actualizado_en,'version',p.version)item FROM catalogo.productos p WHERE p.tenant_id=tenant AND(p_estado IS NULL OR p.estado=p_estado)AND(NULLIF(btrim(p_busqueda),'')IS NULL OR p.nombre ILIKE '%'||btrim(p_busqueda)||'%' OR p.codigo ILIKE '%'||btrim(p_busqueda)||'%')ORDER BY p.nombre,p.id LIMIT p_limit OFFSET p_offset)q;
 RETURN jsonb_build_object('items',items,'total',total,'limit',p_limit,'offset',p_offset);END $$;

CREATE OR REPLACE FUNCTION catalogo.categorias_pagina(p_estado text,p_busqueda text,p_limit integer,p_offset integer)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,catalogo,plataforma,pg_temp AS $$
DECLARE tenant uuid:=plataforma.current_app_tenant_id();items jsonb;total bigint;BEGIN
 IF p_limit NOT BETWEEN 1 AND 100 OR p_offset<0 THEN RAISE EXCEPTION 'Invalid pagination' USING ERRCODE='22023';END IF;IF plataforma.has_current_tenant_capability('erp.catalog','catalog.categories.read') IS NOT TRUE THEN RAISE EXCEPTION 'Category access denied' USING ERRCODE='42501';END IF;
 SELECT count(*) INTO total FROM catalogo.categorias c WHERE c.tenant_id=tenant AND(p_estado IS NULL OR c.estado=p_estado)AND(NULLIF(btrim(p_busqueda),'')IS NULL OR c.nombre ILIKE '%'||btrim(p_busqueda)||'%' OR c.slug ILIKE '%'||btrim(p_busqueda)||'%');
 SELECT COALESCE(jsonb_agg(item ORDER BY sort_order,name,slug),'[]')INTO items FROM(SELECT c.orden sort_order,c.nombre name,c.slug,jsonb_build_object('slug',c.slug,'name',c.nombre,'description',c.descripcion,'parent_slug',c.padre_slug,'status',c.estado,'image_url',c.imagen_url,'sort_order',c.orden,'version',c.version,'product_count',(SELECT count(*)FROM catalogo.productos p WHERE p.tenant_id=c.tenant_id AND p.categoria_ref=c.slug),'updated_at',c.actualizado_en)item FROM catalogo.categorias c WHERE c.tenant_id=tenant AND(p_estado IS NULL OR c.estado=p_estado)AND(NULLIF(btrim(p_busqueda),'')IS NULL OR c.nombre ILIKE '%'||btrim(p_busqueda)||'%' OR c.slug ILIKE '%'||btrim(p_busqueda)||'%')ORDER BY c.orden,c.nombre,c.slug LIMIT p_limit OFFSET p_offset)q;
 RETURN jsonb_build_object('items',items,'total',total,'limit',p_limit,'offset',p_offset);END $$;

CREATE OR REPLACE FUNCTION catalogo.atributos_pagina(p_estado text,p_busqueda text,p_limit integer,p_offset integer)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,catalogo,plataforma,pg_temp AS $$
DECLARE tenant uuid:=plataforma.current_app_tenant_id();items jsonb;total bigint;BEGIN
 IF p_limit NOT BETWEEN 1 AND 100 OR p_offset<0 THEN RAISE EXCEPTION 'Invalid pagination' USING ERRCODE='22023';END IF;IF plataforma.has_current_tenant_capability('erp.catalog','catalog.attributes.read') IS NOT TRUE THEN RAISE EXCEPTION 'Attribute access denied' USING ERRCODE='42501';END IF;
 SELECT count(*)INTO total FROM catalogo.atributos_definiciones a WHERE a.tenant_id=tenant AND(p_estado IS NULL OR a.estado=p_estado)AND(NULLIF(btrim(p_busqueda),'')IS NULL OR a.nombre ILIKE '%'||btrim(p_busqueda)||'%' OR a.codigo ILIKE '%'||btrim(p_busqueda)||'%');
 SELECT COALESCE(jsonb_agg(item ORDER BY sort_order,name,code),'[]')INTO items FROM(SELECT a.orden sort_order,a.nombre name,a.codigo code,jsonb_build_object('code',a.codigo,'name',a.nombre,'type',a.tipo,'required',a.requerido,'options',a.opciones,'unit',a.unidad,'status',a.estado,'sort_order',a.orden,'category_slugs',(SELECT COALESCE(jsonb_agg(x.categoria_slug ORDER BY x.categoria_slug),'[]')FROM catalogo.atributo_categorias x WHERE x.tenant_id=a.tenant_id AND x.codigo=a.codigo),'version',a.version,'updated_at',a.actualizado_en)item FROM catalogo.atributos_definiciones a WHERE a.tenant_id=tenant AND(p_estado IS NULL OR a.estado=p_estado)AND(NULLIF(btrim(p_busqueda),'')IS NULL OR a.nombre ILIKE '%'||btrim(p_busqueda)||'%' OR a.codigo ILIKE '%'||btrim(p_busqueda)||'%')ORDER BY a.orden,a.nombre,a.codigo LIMIT p_limit OFFSET p_offset)q;
 RETURN jsonb_build_object('items',items,'total',total,'limit',p_limit,'offset',p_offset);END $$;

CREATE OR REPLACE FUNCTION catalogo.marcas_pagina(p_estado text,p_busqueda text,p_limit integer,p_offset integer)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,catalogo,plataforma,pg_temp AS $$
DECLARE tenant uuid:=plataforma.current_app_tenant_id();items jsonb;total bigint;BEGIN
 IF p_limit NOT BETWEEN 1 AND 100 OR p_offset<0 THEN RAISE EXCEPTION 'Invalid pagination' USING ERRCODE='22023';END IF;IF plataforma.has_current_tenant_capability('erp.catalog','catalog.brands.read') IS NOT TRUE THEN RAISE EXCEPTION 'Brand access denied' USING ERRCODE='42501';END IF;
 SELECT count(*)INTO total FROM catalogo.marcas m WHERE m.tenant_id=tenant AND(p_estado IS NULL OR m.estado=p_estado)AND(NULLIF(btrim(p_busqueda),'')IS NULL OR m.nombre ILIKE '%'||btrim(p_busqueda)||'%' OR m.slug ILIKE '%'||btrim(p_busqueda)||'%');
 SELECT COALESCE(jsonb_agg(item ORDER BY name,slug),'[]')INTO items FROM(SELECT m.nombre name,m.slug,jsonb_build_object('slug',m.slug,'name',m.nombre,'description',m.descripcion,'logo_url',m.logo_url,'website_url',m.sitio_url,'status',m.estado,'product_count',(SELECT count(*)FROM catalogo.productos p WHERE p.tenant_id=m.tenant_id AND p.marca_ref=m.slug),'version',m.version,'updated_at',m.actualizado_en)item FROM catalogo.marcas m WHERE m.tenant_id=tenant AND(p_estado IS NULL OR m.estado=p_estado)AND(NULLIF(btrim(p_busqueda),'')IS NULL OR m.nombre ILIKE '%'||btrim(p_busqueda)||'%' OR m.slug ILIKE '%'||btrim(p_busqueda)||'%')ORDER BY m.nombre,m.slug LIMIT p_limit OFFSET p_offset)q;
 RETURN jsonb_build_object('items',items,'total',total,'limit',p_limit,'offset',p_offset);END $$;

CREATE OR REPLACE FUNCTION catalogo.proveedores_pagina(p_estado text,p_busqueda text,p_limit integer,p_offset integer)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,catalogo,plataforma,pg_temp AS $$
DECLARE tenant uuid:=plataforma.current_app_tenant_id();items jsonb;total bigint;BEGIN
 IF p_limit NOT BETWEEN 1 AND 100 OR p_offset<0 THEN RAISE EXCEPTION 'Invalid pagination' USING ERRCODE='22023';END IF;IF plataforma.has_current_tenant_capability('erp.catalog','catalog.suppliers.read') IS NOT TRUE THEN RAISE EXCEPTION 'Supplier access denied' USING ERRCODE='42501';END IF;
 SELECT count(*)INTO total FROM catalogo.proveedores_catalogo s JOIN catalogo.terceros t ON(t.tenant_id,t.id)=(s.tenant_id,s.tercero_id)WHERE s.tenant_id=tenant AND(p_estado IS NULL OR s.estado=p_estado)AND(NULLIF(btrim(p_busqueda),'')IS NULL OR t.nombre ILIKE '%'||btrim(p_busqueda)||'%' OR s.codigo ILIKE '%'||btrim(p_busqueda)||'%');
 SELECT COALESCE(jsonb_agg(item ORDER BY name,id),'[]')INTO items FROM(SELECT t.nombre name,t.id,jsonb_build_object('id',t.id,'code',s.codigo,'name',t.nombre,'status',s.estado,'contact',s.contacto,'terms',s.condiciones,'version',s.version,'updated_at',s.actualizado_en)item FROM catalogo.proveedores_catalogo s JOIN catalogo.terceros t ON(t.tenant_id,t.id)=(s.tenant_id,s.tercero_id)WHERE s.tenant_id=tenant AND(p_estado IS NULL OR s.estado=p_estado)AND(NULLIF(btrim(p_busqueda),'')IS NULL OR t.nombre ILIKE '%'||btrim(p_busqueda)||'%' OR s.codigo ILIKE '%'||btrim(p_busqueda)||'%')ORDER BY t.nombre,t.id LIMIT p_limit OFFSET p_offset)q;
 RETURN jsonb_build_object('items',items,'total',total,'limit',p_limit,'offset',p_offset);END $$;

REVOKE ALL ON FUNCTION catalogo.productos_pagina(text,text,integer,integer),catalogo.categorias_pagina(text,text,integer,integer),catalogo.atributos_pagina(text,text,integer,integer),catalogo.marcas_pagina(text,text,integer,integer),catalogo.proveedores_pagina(text,text,integer,integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION catalogo.productos_pagina(text,text,integer,integer),catalogo.categorias_pagina(text,text,integer,integer),catalogo.atributos_pagina(text,text,integer,integer),catalogo.marcas_pagina(text,text,integer,integer),catalogo.proveedores_pagina(text,text,integer,integer) TO mastererp_app;
